def first_app_frame(trace, package):
    needle = f'at {package}.'
    for line in trace.splitlines():
        line = line.strip()
        if line.startswith(needle):
            return line
    return None

import re

def group_failures(failures):
    groups = {}
    for f in failures:
        sig = re.sub(r'0x[0-9a-fA-F]+', 'ID', f['error'])
        sig = re.sub(r'\d+', 'N', sig)
        groups.setdefault(sig, []).append(f['test'])
    return {k: sorted(v) for k, v in groups.items()}
